import pytest

def test_empty_data_with_maxcolwidths():
    import pytest
    from tabulate import tabulate

    # Empty data without headers
    try:
        result = tabulate([], maxcolwidths=[10, 20])
    except Exception as e:
        pytest.fail(f"Unexpected exception with empty data and maxcolwidths: {e}")
    assert isinstance(result, str)

    # Empty data with headers
    try:
        result = tabulate([], headers=("A", "B"), maxcolwidths=[10, 20])
    except Exception as e:
        pytest.fail(f"Unexpected exception with empty data, headers, and maxcolwidths: {e}")
    assert isinstance(result, str)

